function owns(kind,index){return kind==='pilot'?pilotPrices[index]===0||!!profile?.owned?.some(x=>x.kind===kind&&x.item_id===index):index===0||!!profile?.owned?.some(x=>x.kind===kind&&x.item_id===index)}
async function api(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});let json;try{json=await response.json()}catch{throw Error('Sem conexão com a garagem. Tente novamente.')}if(!response.ok){const e=new Error(json.error||'Não foi possível salvar.');e.status=response.status;throw e}return json}
function applyProfile(data,restore=false){profile=data;profileOnline=!!data;$('#wallet').hidden=!profile;$('#wallet').textContent=profile?'✦ '+profile.coins:'';$('#account').textContent=profile?(profile.xHandle?'@'+profile.xHandle:profile.nickname):'Entrar com 𝕏';if(profile){recordData={...profile.records};if(restore&&profile.garage){driver=profile.garage.pilot;selectedVehicle=profile.garage.vehicle;custom={paint:profile.garage.paint,wheels:profile.garage.wheels,spoiler:profile.garage.spoiler};$('#driverName').textContent=pilots[driver].name+' · '+pilots[driver].trait;if(state==='menu')setupMenuKart()}if($('#xProfileCard')){$('#xProfileCard').hidden=false;$('#xLoginForm').hidden=true;$('#xUserNick').textContent=profile.nickname||'Piloto 𝕏';$('#xUserHandle').textContent=profile.xHandle?'@'+profile.xHandle:'@Piloto';$('#xUserCoins').textContent='✦ '+(profile.coins||0);$('#xUserPilots').textContent=pilots.filter((_,i)=>owns('pilot',i)).length+' / '+pilots.length;$('#xUserKarts').textContent=vehicles.filter((_,i)=>owns('vehicle',i)).length+' / '+vehicles.length;const av=profile.avatar||(profile.xHandle?'https://unavatar.io/twitter/'+profile.xHandle:'./icon-192.png');$('#xUserAvatar').src=av;$('#xUserAvatar').onerror=()=>{$('#xUserAvatar').src='./icon-192.png'}}}else{if($('#xProfileCard')){$('#xProfileCard').hidden=true;$('#xLoginForm').hidden=false}}document.querySelectorAll('[data-driver]').forEach(b=>{let i=+b.dataset.driver;b.classList.toggle('locked',!owns('pilot',i));b.classList.toggle('active',i===driver);b.setAttribute('aria-pressed',i===driver)});$('#vehicleName').textContent=vehicles[selectedVehicle].name;refreshRecord();}
async function loadProfile(){try{const check=await fetch('/api/auth/x').then(r=>r.json()).catch(()=>null);if($('#oauthSection'))$('#oauthSection').hidden=!check?.oauthConfigured;}catch{}try{const data=await api('profile');applyProfile(data.profile,true);$('#accountStatus').textContent=data.profile?'Conectado ao 𝕏! Garagem e moedas sincronizadas.':'Conecte sua conta do 𝕏 para salvar seus recordes e moedas.';if(data.profile?.xHandle&&$('#xHandle'))$('#xHandle').value=data.profile.xHandle;if(data.profile?.nickname&&$('#nickname'))$('#nickname').value=data.profile.nickname}catch(e){try{const saved=JSON.parse(localStorage.getItem('misuki-x-profile')||'null');if(saved){applyProfile(saved,true);$('#accountStatus').textContent='Perfil carregado do dispositivo.';return}}catch{}$('#accountStatus').textContent='Conecte com o 𝕏 para desbloquear pilotos, karts e salvar seu progresso!';applyProfile(null)}}
function shopMessage(text){$('#shopStatus').textContent=text}
let shopTab='pilots',shopBusy=false,workshopDraft=null;
function vehicleThumbs(){if(vehicleImages.length)return;const s=new THREE.Scene();s.background=new THREE.Color(0x2c2544);s.add(new THREE.HemisphereLight(0xffffff,0x5d4890,2.4));const l=new THREE.DirectionalLight(0xffffff,3);l.position.set(3,6,5);s.add(l);const c=new THREE.PerspectiveCamera(38,1.6,.1,50);c.position.set(4,3.5,6);c.lookAt(0,1,0);renderer.setSize(300,190,false);for(let j=0;j<vehicles.length;j++){let g=kartModel(driver,j,{paint:'original',wheels:j===2?3:0,spoiler:0});s.add(g);renderer.render(s,c);vehicleImages.push(renderer.domElement.toDataURL('image/webp',.85));s.remove(g);g.traverse(m=>{if(m.geometry&&!Object.values(geo).includes(m.geometry))m.geometry.dispose()})}resize()}
function renderShop(){vehicleThumbs();$('#shopBalance').textContent=profile?'✦ '+profile.coins:'Crie um perfil para comprar';document.querySelectorAll('[data-shop-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.shopTab===shopTab));const list=shopTab==='pilots'?pilots:vehicles;$('#shopGrid').innerHTML=list.map((item,i)=>{let kind=shopTab==='pilots'?'pilot':'vehicle',price=kind==='pilot'?pilotPrices[i]:item.price,owned=owns(kind,i),chosen=kind==='pilot'?driver===i:selectedVehicle===i;return `<article class="shop-card"><img src="${kind==='pilot'?pilotImages[i]:vehicleImages[i]}" alt="${item.name}"><div><b>${item.name}</b><p>${kind==='pilot'?item.trait:item.desc}</p><button data-buy-kind="${kind}" data-buy-id="${i}" ${chosen?'disabled':''}>${chosen?'Equipado':owned?'Equipar':'✦ '+price+' · Comprar'}</button></div></article>`}).join('')}
function openShop(tab='pilots'){shopTab=tab;shopMessage('Moedas do jogo: ganhe completando corridas.');renderShop();if(!$('#shopDialog').open)$('#shopDialog').showModal()}
async function equip(kind,index){if(kind==='pilot'){driver=index;selectDriver(index)}else{selectedVehicle=index;setupMenuKart();$('#vehicleName').textContent=vehicles[index].name}if(profile){const saved=await api('garage',{pilot:driver,vehicle:selectedVehicle,...custom});applyProfile(saved.profile)}renderShop()}
async function buy(kind,index){if(shopBusy)return;if(!profile){shopMessage('Crie seu perfil de piloto antes de comprar.');return}shopBusy=true;const previous={driver,selectedVehicle};try{if(!owns(kind,index)){const result=await api('purchase',{kind,item:index});applyProfile(result.profile);shopMessage('Compra concluída! O item já é seu.')}await equip(kind,index)}catch(e){driver=previous.driver;selectedVehicle=previous.selectedVehicle;if(state==='menu')setupMenuKart();shopMessage(e.message)}finally{shopBusy=false}}
function renderWorkshop(){workshopDraft={vehicle:selectedVehicle,...custom};$('#bodySelect').innerHTML=vehicles.map((v,i)=>owns('vehicle',i)?`<option value="${i}">${v.name}</option>`:'').join('');$('#bodySelect').value=selectedVehicle;$('#paintSelect').innerHTML=paintColors.map((c,i)=>`<option value="${c}">${['Cor do piloto','Lilás Misuki','Rosa Sakura','Azul elétrico','Verde rush','Laranja solar','Branco pérola','Preto noturno','Vermelho rubro'][i]}</option>`).join('');$('#paintSelect').value=custom.paint;$('#wheelSelect').innerHTML=wheelNames.map((n,i)=>`<option value="${i}">${n}</option>`).join('');$('#wheelSelect').value=custom.wheels;$('#spoilerSelect').innerHTML=spoilerNames.map((n,i)=>`<option value="${i}">${n}</option>`).join('');$('#spoilerSelect').value=custom.spoiler;previewWorkshop()}
function previewWorkshop(){if(!workshopDraft)return;workshopDraft={vehicle:Number($('#bodySelect').value),paint:$('#paintSelect').value,wheels:Number($('#wheelSelect').value),spoiler:Number($('#spoilerSelect').value)};clearKarts();const g=kartModel(driver,workshopDraft.vehicle,workshopDraft);g.scale.multiplyScalar(1.8);scene.add(g);karts=[{g,s:30,lane:0,pilot:driver}];poseKart(g,30,0);const s=new THREE.Scene();s.background=new THREE.Color(0x29213c);s.add(new THREE.HemisphereLight(0xffffff,0x795393,2.5));let l=new THREE.DirectionalLight(0xffffff,3);l.position.set(4,8,5);s.add(l);const c=new THREE.PerspectiveCamera(38,1.7,.1,50);c.position.set(7,5,10);c.lookAt(0,2,0);const preview=kartModel(driver,workshopDraft.vehicle,workshopDraft);preview.scale.multiplyScalar(1.8);s.add(preview);renderer.setSize(510,300,false);renderer.render(s,c);$('#workshopPreview').src=renderer.domElement.toDataURL('image/webp',.9);preview.traverse(m=>{if(m.geometry&&!Object.values(geo).includes(m.geometry))m.geometry.dispose()});resize();}
async function saveWorkshop(){const b=$('#saveWorkshop');b.disabled=true;try{if(profile){const result=await api('garage',{pilot:driver,...workshopDraft});applyProfile(result.profile)}selectedVehicle=workshopDraft.vehicle;custom={paint:workshopDraft.paint,wheels:workshopDraft.wheels,spoiler:workshopDraft.spoiler};if(!profile)try{localStorage.setItem('misuki-preferences',JSON.stringify({vehicle:0,...custom}))}catch{}$('#vehicleName').textContent=vehicles[selectedVehicle].name;setupMenuKart();$('#workshopDialog').close();workshopDraft=null}catch(e){$('#workshopStatus').textContent=e.message}finally{b.disabled=false}}
